+        line-height: 1.7;
+      }
+
+      .example[data-open="true"] .details {
+        grid-template-rows: 1fr;
+      }
+
+      .example[data-open="true"] .chevron {
+        transform: rotate(180deg);
+        background: #e6ecff;
+      }
+
+      .footer-note {
+        margin-top: 20px;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
