+        paragraph.textContent = answer;
+
+        inner.appendChild(paragraph);
+        details.appendChild(inner);
+
+        button.addEventListener("click", () => {
+          const isOpen = item.dataset.open === "true";
+          item.dataset.open = String(!isOpen);
+          button.setAttribute("aria-expanded", String(!isOpen));
+          details.hidden = isOpen;
+        });
+
+        item.append(button, details);
+        return item;
+      }
+
+      function FAQPage() {
+        const root = document.createElement("div");
+        root.className = "page-shell";
+
+        const hero = document.createElement("section");
+        hero.className = "hero";
+
+        const eyebrow = document.createElement("div");
+        eyebrow.className = "eyebrow";
+        eyebrow.textContent = "Cat FAQ";
+
+        const title = document.createElement("h1");
+        title.textContent = "Everything you wanted to know about cats.";
+
+        const subtitle = document.createElement("p");
+        subtitle.className = "subtitle";
+        subtitle.textContent =
+          "A clean, modern FAQ with expandable answers, built with a React-style component structure and shipped as a single standalone HTML document.";
+
+        hero.append(eyebrow, title, subtitle);
+
+        const list = document.createElement("section");
+        list.className = "faq";
