<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: rgba(255, 255, 255, 0.82);
        --panel-border: rgba(15, 23, 42, 0.08);
        --text: #111827;
        --muted: #5b6472;
        --accent: #6d5efc;
        --accent-soft: #efeaff;
        --shadow: 0 24px 80px rgba(15, 23, 42, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #efeaff 0, transparent 34%),
          radial-gradient(circle at top right, #dff7ff 0, transparent 28%),
          linear-gradient(180deg, #fbfcff 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      .page {
        width: min(980px, calc(100% - 32px));
        margin: 0 auto;
        padding: 48px 0 64px;
      }

      .hero {
        margin-bottom: 24px;
        padding: 32px;
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        background: var(--panel);
        backdrop-filter: blur(16px);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 16px 0 10px;
        font-size: clamp(2.25rem, 4vw, 4rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
      }

      .subtitle {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .faq {
        display: grid;
        gap: 16px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 22px;
        background: rgba(255, 255, 255, 0.9);
        box-shadow: 0 12px 40px rgba(15, 23, 42, 0.08);
        overflow: hidden;
      }

      .question {
        width: 100%;
        padding: 20px 22px;
        border: 0;
        background: transparent;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        color: var(--text);
        font: inherit;
        text-align: left;
        cursor: pointer;
      }

      .question:focus-visible {
        outline: 3px solid rgba(109, 94, 252, 0.35);
        outline-offset: -3px;
      }

      .question-text {
        display: block;
        font-size: 1.05rem;
        font-weight: 700;
        line-height: 1.4;
      }

      .chevron {
        flex: 0 0 auto;
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: var(--accent-soft);
        color: var(--accent);
        display: grid;
        place-items: center;
        transition: transform 180ms ease, background 180ms ease;
      }

      .details {
        display: grid;
        grid-template-rows: 0fr;
        transition: grid-template-rows 220ms ease;
      }

      .details-inner {
        overflow: hidden;
      }

      .answer {
        padding: 0 22px 22px;
        margin: 0;
        color: var(--muted);
        line-height: 1.7;
      }

      .example[data-open="true"] .details {
        grid-template-rows: 1fr;
      }

      .example[data-open="true"] .chevron {
        transform: rotate(180deg);
        background: #e6ecff;
      }

      .footer-note {
        margin-top: 20px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 980px);
          padding-top: 20px;
        }

        .hero {
          padding: 24px;
        }

        .question {
          padding: 18px 18px;
        }

        .answer {
          padding: 0 18px 18px;
        }
      }
    </style>
  </head>
  <body>
    <main id="app" class="page" aria-label="Cat frequently asked questions"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comfort behavior that often starts in kittenhood. Adult cats usually keep doing it when they feel safe, relaxed, or especially attached to you.",
        },
        {
          question: "Why do cats sleep so much?",
          answer:
            "Cats are natural energy savers. They sleep a lot because their bodies are designed for short bursts of hunting, play, and zoomies rather than constant activity.",
        },
        {
          question: "Do cats need a lot of companionship?",
          answer:
            "Most cats enjoy regular attention, but the amount varies by personality. Some want constant interaction, while others prefer quiet companionship from a little distance.",
        },
        {
          question: "How can I make my cat feel at home?",
          answer:
            "Give your cat a quiet hideaway, fresh water, a clean litter box, and a predictable routine. Let them explore on their own terms, and they'll usually settle in faster.",
        },
      ];

      function FAQItem({ question, answer }, index) {
        const item = document.createElement("div");
        item.className = "example";
        item.dataset.open = "false";

        const button = document.createElement("button");
        button.className = "question";
        button.type = "button";
        button.setAttribute("aria-expanded", "false");
        button.setAttribute("aria-controls", `faq-answer-${index}`);

        const label = document.createElement("span");
        label.className = "question-text";
        label.textContent = question;

        const chevron = document.createElement("span");
        chevron.className = "chevron";
        chevron.setAttribute("aria-hidden", "true");
        chevron.textContent = "⌄";

        button.append(label, chevron);

        const details = document.createElement("div");
        details.className = "details";
        details.id = `faq-answer-${index}`;
        details.hidden = true;

        const inner = document.createElement("div");
        inner.className = "details-inner";

        const paragraph = document.createElement("p");
        paragraph.className = "answer";
        paragraph.textContent = answer;

        inner.appendChild(paragraph);
        details.appendChild(inner);

        button.addEventListener("click", () => {
          const isOpen = item.dataset.open === "true";
          item.dataset.open = String(!isOpen);
          button.setAttribute("aria-expanded", String(!isOpen));
          details.hidden = isOpen;
        });

        item.append(button, details);
        return item;
      }

      function FAQPage() {
        const root = document.createElement("div");
        root.className = "page-shell";

        const hero = document.createElement("section");
        hero.className = "hero";

        const eyebrow = document.createElement("div");
        eyebrow.className = "eyebrow";
        eyebrow.textContent = "Cat FAQ";

        const title = document.createElement("h1");
        title.textContent = "Everything you wanted to know about cats.";

        const subtitle = document.createElement("p");
        subtitle.className = "subtitle";
        subtitle.textContent =
          "A clean, modern FAQ with expandable answers, built with a React-style component structure and shipped as a single standalone HTML document.";

        hero.append(eyebrow, title, subtitle);

        const list = document.createElement("section");
        list.className = "faq";
        list.setAttribute("aria-label", "Cat FAQ questions");
        faqs.forEach((faq, index) => list.appendChild(FAQItem(faq, index)));

        const note = document.createElement("p");
        note.className = "footer-note";
        note.textContent = "Tip: Click any question to expand its answer.";

        root.append(hero, list, note);
        return root;
      }

      document.getElementById("app").appendChild(FAQPage());
    </script>
  </body>
</html>
